/* Language runtime (every page). English is the source text; translated pages (/es/, /pt/, …) load
 * assets/i18n/<lang>.js first, which sets window.LUMI_I18N = {lang, locale, strings} (generated by scripts/i18n.py from
 * assets/i18n/<lang>.json). Other scripts call LumiI18n.t("English text {x}", {x: 1}); a missing key falls back to English.
 * Also: remembers the language picked in the header menu (.lang-menu, static links built by build_pages.py) in
 * localStorage "lumi_lang", and shows a gentle, dismissible suggestion when the visitor's saved choice or browser
 * language has a translation of this page. Never redirects. */
(() => {
  "use strict";
  const D = window.LUMI_I18N || {};
  const lang = D.lang || document.documentElement.lang || "en";
  const S = D.strings || {};
  const KEY = "lumi_lang";
  function t(s, vars) {
    let out = (lang !== "en" && S[s]) || s;
    if (vars) out = out.replace(/\{(\w+)\}/g, (m, k) => (k in vars ? String(vars[k]) : m));
    return out;
  }
  window.LumiI18n = { lang, locale: D.locale || "en-US", t, en: lang === "en" };

  // suggestion text, in the language being suggested (short on purpose)
  const ASK = {
    en: ["This page is also available in English.", "View in English", "Dismiss"],
    es: ["Esta página también está disponible en español.", "Ver en español", "Cerrar"],
    pt: ["Esta página também está disponível em português.", "Ver em português", "Fechar"],
    tr: ["Bu sayfanın Türkçe sürümü de var.", "Türkçe görüntüle", "Kapat"],
    ko: ["이 페이지는 한국어로도 볼 수 있습니다.", "한국어로 보기", "닫기"],
    ja: ["このページは日本語でもご覧いただけます。", "日本語で見る", "閉じる"],
  };
  const get = (k) => { try { return localStorage.getItem(k); } catch (e) { return null; } };
  const set = (k, v) => { try { localStorage.setItem(k, v); } catch (e) { /* private mode */ } };

  function init() {
    const menu = document.querySelector(".lang-menu");
    if (!menu) return;
    const links = [...menu.querySelectorAll("a[data-lang]")];
    links.forEach((a) => a.addEventListener("click", () => set(KEY, a.dataset.lang)));
    document.addEventListener("click", (e) => { if (menu.open && !menu.contains(e.target)) menu.open = false; });
    document.addEventListener("keydown", (e) => { if (e.key === "Escape") menu.open = false; });
    // gentle suggestion: saved choice first, else the first browser language we have; never on a page in that language
    if (get("lumi_lang_hint") === "off") return;
    const have = Object.fromEntries(links.map((a) => [a.dataset.lang, a]));
    let want = get(KEY);
    if (!want) {
      const nav = (navigator.languages || [navigator.language || ""]).map((x) => String(x).toLowerCase().slice(0, 2));
      want = nav.find((x) => have[x]) || "";
      if (want === "en" || (nav[0] && nav[0] !== want)) return; // only when the browser's top language is one we have
    }
    if (!want || want === lang || !have[want] || !ASK[want]) return;
    const [msg, go, close] = ASK[want];
    const bar = document.createElement("div");
    bar.className = "lang-hint"; bar.setAttribute("role", "note"); bar.lang = want;
    bar.innerHTML = `<span></span> <a></a> <button type="button"></button>`;
    bar.querySelector("span").textContent = msg;
    const a = bar.querySelector("a"); a.textContent = go; a.href = have[want].getAttribute("href"); a.hreflang = want;
    a.addEventListener("click", () => set(KEY, want));
    const b = bar.querySelector("button"); b.textContent = "✕"; b.setAttribute("aria-label", close);
    b.addEventListener("click", () => { bar.remove(); set("lumi_lang_hint", "off"); if (!get(KEY)) set(KEY, lang); });
    const top = document.querySelector("header");
    top ? top.insertAdjacentElement("afterend", bar) : document.body.prepend(bar);
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", init); else init();
})();
